import java.util.PriorityQueue;

class Completed {

    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {

        int n = profits.length;

        PriorityQueue<int[]> projectsByCapital = new PriorityQueue<>(
            (a, b) -> Integer.compare(a[0], b[0])
        );

        for (int i = 0; i < n; i++) {
            projectsByCapital.offer(new int[]{capital[i], profits[i]});
        }

        PriorityQueue<Integer> availableProfits = new PriorityQueue<>(
            (a, b) -> Integer.compare(b, a)
        );

        for (int i = 0; i < k; i++) {

            while (!projectsByCapital.isEmpty() && projectsByCapital.peek()[0] <= w) {
                availableProfits.offer(projectsByCapital.poll()[1]);
            }

            if (availableProfits.isEmpty()) {
                break;
            }

            w += availableProfits.poll();
        }

        return w;
    }
}

